INSERT INTO public.site_settings (setting_key, setting_value, setting_group) VALUES
('vision', 'أن نكون كلية رائدة في تعليم وبحوث علوم الحاسوب وتقنية المعلومات على المستوى المحلي والإقليمي، ومرجعًا أكاديميًا معتمدًا يخدم احتياجات المجتمع وسوق العمل.', 'about'),
('mission', 'إعداد خريجين متميزين علميًا ومهنيًا في تخصصات تقنية المعلومات وعلوم الحاسوب، وإجراء بحوث علمية تطبيقية تخدم القطاع التقني والمؤسسات الحكومية والخاصة، وتعزيز الشراكة المجتمعية.', 'about'),
('dean_name', 'أ.د. عبدالله محمد الصبري', 'about'),
('dean_title', 'عميد كلية تكنولوجيا المعلومات وعلوم الحاسوب', 'about'),
('dean_message', 'يسعدني أن أرحّب بكم في البوابة الرسمية لكلية تكنولوجيا المعلومات وعلوم الحاسوب بجامعة إقليم سبأ. نسعى في كليتنا إلى إعداد جيل من المتخصصين القادرين على مواكبة التطور التقني المتسارع، عبر برامج أكاديمية حديثة، وكادر تدريسي متميز، وبيئة تعليمية محفّزة. ندعوكم لاكتشاف برامجنا والانضمام إلى أسرة الكلية.', 'about')
